package com.learnknow.course;

import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
import com.learnknow.course.model.Course; import com.learnknow.course.model.Module; import com.learnknow.course.model.Resource; import com.learnknow.course.repository.CourseRepository; import com.learnknow.course.repository.ModuleRepository; import com.learnknow.course.repository.ResourceRepository;
@SpringBootApplication public class CourseServiceApplication { public static void main(String[] args){SpringApplication.run(CourseServiceApplication.class,args);}
public record CourseRequest(@NotBlank String title,String description,String level){} public record ModuleRequest(@NotBlank String title,Integer sequenceNo){} public record ResourceRequest(@NotBlank String title,String resourceType,String contentUrl,String accessLevel){}
@RestController @RequestMapping("/api/courses") public static class Controller { private final CourseRepository courses; private final ModuleRepository modules; private final ResourceRepository resources; Controller(CourseRepository c,ModuleRepository m,ResourceRepository r){courses=c;modules=m;resources=r;} @GetMapping List<Course> all(){return courses.findAll();} @GetMapping("/{id}") Course one(@PathVariable("id") Long id){return courses.findById(id).orElseThrow(()->new NoSuchElementException("Course not found"));} @PostMapping @ResponseStatus(HttpStatus.CREATED) Course create(@Valid @RequestBody CourseRequest r){Course c=new Course();c.title=r.title();c.description=r.description();c.level=r.level();return courses.save(c);} @PutMapping("/{id}") Course update(@PathVariable("id") Long id,@Valid @RequestBody CourseRequest r){Course c=one(id);c.title=r.title();c.description=r.description();c.level=r.level();return courses.save(c);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable("id") Long id){courses.delete(one(id));} @GetMapping("/{courseId}/modules") List<Module> mods(@PathVariable("courseId") Long courseId){one(courseId);return modules.findByCourseIdOrderBySequenceNo(courseId);} @PostMapping("/{courseId}/modules") @ResponseStatus(HttpStatus.CREATED) Module addMod(@PathVariable("courseId") Long courseId,@Valid @RequestBody ModuleRequest r){one(courseId);Module m=new Module();m.courseId=courseId;m.title=r.title();m.sequenceNo=r.sequenceNo();return modules.save(m);} @GetMapping("/modules/{moduleId}/resources") List<Resource> res(@PathVariable("moduleId") Long moduleId){return resources.findByModuleId(moduleId);} @PostMapping("/modules/{moduleId}/resources") @ResponseStatus(HttpStatus.CREATED) Resource addRes(@PathVariable("moduleId") Long moduleId,@Valid @RequestBody ResourceRequest r){Resource x=new Resource();x.moduleId=moduleId;x.title=r.title();x.resourceType=r.resourceType();x.contentUrl=r.contentUrl();x.accessLevel=r.accessLevel()==null?"ENROLLED":r.accessLevel();return resources.save(x);} }
@RestControllerAdvice public static class Errors{@ExceptionHandler(NoSuchElementException.class) @ResponseStatus(HttpStatus.NOT_FOUND) Map<String,String> missing(Exception e){return Map.of("error",e.getMessage());}}
}
